const dataPath=path.join(root,'app/data.ts');let data=fs.readFileSync(dataPath,'utf8');
if(!data.includes("from './blog-october13'"))data=data.replace("import { october8BlogPosts, october8BlogDetails } from './blog-october8';","import { october8BlogPosts, october8BlogDetails } from './blog-october8';\nimport { october13BlogPosts, october13BlogDetails } from './blog-october13';");
if(!data.includes('...october13BlogPosts'))data=data.replace('export const blogPosts = [\n  ...october12BlogPosts,','export const blogPosts = [\n  ...october13BlogPosts,\n  ...october12BlogPosts,');
if(!data.includes('...october13BlogDetails'))data=data.replace('export const blogDetails = {\n  ...october12BlogDetails,','export const blogDetails = {\n  ...october13BlogDetails,\n  ...october12BlogDetails,');
