const fleetPath=path.join(root,'app/fleet-data.ts');let fleet=fs.readFileSync(fleetPath,'utf8');
if(!fleet.includes("from './research-october13'"))fleet=fleet.replace("import { october8ResearchPosts } from './research-october8';","import { october8ResearchPosts } from './research-october8';\nimport { october13ResearchPosts } from './research-october13';");
if(!fleet.includes('...october13ResearchPosts'))fleet=fleet.replace('export const researchPosts: readonly ResearchPost[] = [\n  ...october12ResearchPosts,','export const researchPosts: readonly ResearchPost[] = [\n  ...october13ResearchPosts,\n  ...october12ResearchPosts,');
fs.writeFileSync(fleetPath,fleet);
